mapper.select:
SELECT a.id, a.run_id, a.session_id, a.step_seq, a.tool_code, t.name AS tool_name, a.arguments, a.reason, a.status, a.operator_id, a.operated_at, a.comment, a.expire_at, a.create_time FROM agent_approval a LEFT JOIN agent_tool t ON t.code = a.tool_code
a.status = #{status}
ORDER BY a.create_time DESC, a.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT *
FROM agent_approval
WHERE run_id = #{runId}
  AND step_seq = #{stepSeq}
  AND tool_code = #{toolCode}
  AND status = 'pending'
ORDER BY id DESC
LIMIT 1

mapper.update:
UPDATE agent_approval
SET status = #{status}
WHERE id = #{id}
  AND status = 'executing'
